-- Migration 0035_staff_workspace_usage: generated by drizzle-kit (the columns, FK and check), policy, functions and grants hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #224)
-- The staff console's workspace usage view (#224, #30 part 7; docs/engineering/admin-console.md):
--   * budget_override gains expired_at, expired_by and expire_reason: staff may expire an override
--     early, and who did it and why stay on the row (all three set or none, the reason non-blank).
--     Audit metadata holds identifiers only, so the reason cannot live there.
--   * owner_definer_read on budget_override lets only the owner (and so only definer functions)
--     read it across workspaces; usage_counter has one already (0018).
--   * app_staff_workspace_usage(ws) and app_staff_budget_overrides(ws, max) are SECURITY DEFINER
--     and first refuse (42501) unless app.user_id is an enabled staff_user
--     (app_staff_require_caller, 0033). They return keys, numbers, ids, dates and the staff-written
--     reasons only, never customer content.
-- Additive only; the previous release never reads the new columns or calls the functions.
ALTER TABLE "budget_override" ADD COLUMN "expired_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "budget_override" ADD COLUMN "expired_by" uuid;--> statement-breakpoint
ALTER TABLE "budget_override" ADD COLUMN "expire_reason" text;--> statement-breakpoint
ALTER TABLE "budget_override" ADD CONSTRAINT "budget_override_expired_by_user_id_fk" FOREIGN KEY ("expired_by") REFERENCES "public"."user"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "budget_override" ADD CONSTRAINT "budget_override_expiry_chk" CHECK ((expired_at is null and expired_by is null and expire_reason is null) or (expired_at is not null and expired_by is not null and expire_reason is not null and length(btrim(expire_reason)) > 0));--> statement-breakpoint
CREATE POLICY "owner_definer_read" ON "budget_override" AS PERMISSIVE FOR SELECT TO causedeck_owner
  USING (true);--> statement-breakpoint
-- The newest period's counter per key for `ws`, by key.
CREATE FUNCTION app_staff_workspace_usage(ws uuid)
  RETURNS TABLE (key text, period_start timestamptz, value bigint)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    #variable_conflict use_column
    BEGIN
      PERFORM app_staff_require_caller();
      RETURN QUERY
        SELECT DISTINCT ON (c.key) c.key, c.period_start, c.value
          FROM usage_counter c
         WHERE c.workspace_id = ws
         ORDER BY c.key, c.period_start DESC;
    END
  $$;--> statement-breakpoint
-- The budget overrides of `ws`, newest first (at most `max`, up to 100).
CREATE FUNCTION app_staff_budget_overrides(ws uuid, max integer)
  RETURNS TABLE (
    id uuid, key text, limit_value bigint, set_by uuid, reason text, expires_at timestamptz,
    created_at timestamptz, expired_at timestamptz, expired_by uuid, expire_reason text
  )
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    #variable_conflict use_column
    BEGIN
      PERFORM app_staff_require_caller();
      RETURN QUERY
        SELECT b.id, b.key, b.limit_value, b.set_by, b.reason, b.expires_at, b.created_at,
               b.expired_at, b.expired_by, b.expire_reason
          FROM budget_override b
         WHERE b.workspace_id = ws
         ORDER BY b.created_at DESC, b.id DESC
         LIMIT least(greatest(coalesce(max, 50), 1), 100);
    END
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_staff_workspace_usage(uuid), app_staff_budget_overrides(uuid, integer) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_staff_workspace_usage(uuid), app_staff_budget_overrides(uuid, integer) TO causedeck_app, causedeck_clerk;
